15	declare_lint_rule! {
16	    /// Disallow type conversions that do not change the type of an expression.
17	    ///
18	    /// This rule reports common conversion patterns when the converted expression
19	    /// is already known to have the target base type (AKA primitive type).
20	    ///
21	    /// ## Examples
22	    ///
23	    /// ### Invalid
24	    ///
25	    /// ```ts,expect_diagnostic,file=invalid-string.ts
26	    /// const text: string = "text";
27	    /// String(text);
28	    /// ```
29	    ///
30	    /// ```ts,expect_diagnostic,file=invalid-boolean.ts
31	    /// const value: boolean = true;
32	    /// !!value;
33	    /// ```
34	    ///
35	    /// ```ts,expect_diagnostic,file=invalid-assignment.ts
36	    /// let str = "text";
37	    /// str += "";
38	    /// ```
39	    ///
40	    /// ### Valid
41	    ///
42	    /// Genuine conversions are allowed.
43	    /// ```ts
44	    /// String(1);
45	    /// !!0;
46	    /// ```
47	    ///
48	    /// Unboxing boxed values is allowed.
49	    /// ```ts
50	    /// String(new String());
51	    /// ```
52	    pub NoUselessTypeConversion {
53	        version: "2.4.11",
54	        name: "noUselessTypeConversion",
55	        language: "js",
56	        recommended: false,
57	        sources: &[RuleSource::EslintTypeScript("no-unnecessary-type-conversion").same()],
58	        domains: &[RuleDomain::Types],
59	        issue_number: Some("9752"),
60	    }
61	}
