80	enum ConversionKind {
81	    /// `String(value)`, `Number(value)`, `Boolean(value)`, or `BigInt(value)`.
82	    BuiltinCall,
83	    /// `value.toString()`.
84	    ToString,
85	    /// `value + ""` or `"" + value`.
86	    StringConcatenation,
87	    /// `value += ""`.
88	    StringAssignment,
89	    /// `+value`.
90	    UnaryPlus,
91	    /// `!!value`.
92	    DoubleNegation,
93	    /// `~~value`.
94	    DoubleBitwiseNot,
95	}
