104	impl Rule for NoUselessTypeConversion {
105	    type Query = Typed<AnyPotentialUselessTypeConversion>;
106	    type State = RuleState;
107	    type Signals = Option<Self::State>;
108	    type Options = NoUselessTypeConversionOptions;
109	
110	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
111	        match ctx.query() {
112	            AnyPotentialUselessTypeConversion::JsCallExpression(call) => {
113	                run_builtin_call(ctx, call).or_else(|| run_to_string_call(ctx, call))
114	            }
115	            AnyPotentialUselessTypeConversion::JsUnaryExpression(unary) => {
116	                run_unary_expression(ctx, unary)
117	            }
118	            AnyPotentialUselessTypeConversion::JsBinaryExpression(binary) => {
119	                run_binary_expression(ctx, binary)
120	            }
121	            AnyPotentialUselessTypeConversion::JsAssignmentExpression(assignment) => {
122	                run_assignment_expression(ctx, assignment)
123	            }
124	        }
125	    }
126	
127	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
128	        let (article, name) = match (state.kind, state.primitive) {
129	            (ConversionKind::DoubleBitwiseNot, PrimitiveKind::Number) => {
130	                ("an integer-like number", "number")
131	            }
132	            (_, PrimitiveKind::String) => ("a string", "string"),
133	            (_, PrimitiveKind::Number) => ("a number", "number"),
134	            (_, PrimitiveKind::Boolean) => ("a boolean", "boolean"),
135	            (_, PrimitiveKind::BigInt) => ("a bigint", "bigint"),
136	        };
137	
138	        let message = match state.kind {
139	            ConversionKind::BuiltinCall => match state.primitive {
140	                PrimitiveKind::String => "Avoid calling `String()` on a string value.",
141	                PrimitiveKind::Number => "Avoid calling `Number()` on a number value.",
142	                PrimitiveKind::Boolean => "Avoid calling `Boolean()` on a boolean value.",
143	                PrimitiveKind::BigInt => "Avoid calling `BigInt()` on a bigint value.",
144	            },
145	            ConversionKind::ToString => "Avoid calling `toString()` on a string value.",
146	            ConversionKind::StringConcatenation => {
147	                "Avoid concatenating a string value with an empty string."
148	            }
149	            ConversionKind::StringAssignment => {
150	                "Avoid appending an empty string to a string value."
151	            }
152	            ConversionKind::UnaryPlus => "Avoid applying unary `+` to a number value.",
153	            ConversionKind::DoubleNegation => "Avoid applying `!!` to a boolean value.",
154	            ConversionKind::DoubleBitwiseNot => match state.primitive {
155	                PrimitiveKind::BigInt => "Avoid applying `~~` to a bigint value.",
156	                _ => "Avoid applying `~~` to an integer value.",
157	            },
158	        };
159	
160	        let note = match state.kind {
161	            ConversionKind::BuiltinCall | ConversionKind::ToString => {
162	                "Remove the conversion and use the value directly."
163	            }
164	            ConversionKind::StringConcatenation | ConversionKind::StringAssignment => {
165	                "This expression already evaluates to a string, so the empty string has no effect."
166	            }
167	            ConversionKind::UnaryPlus => {
168	                "This expression already evaluates to a number, so the unary operator has no effect."
169	            }
170	            ConversionKind::DoubleNegation => {
171	                "This expression already evaluates to a boolean, so the double negation has no effect."
172	            }
173	            ConversionKind::DoubleBitwiseNot => match state.primitive {
174	                PrimitiveKind::BigInt => {
175	                    "This expression already evaluates to a bigint, so the double bitwise NOT has no effect."
176	                }
177	                _ => {
178	                    "This expression already evaluates to an integer-like number, so the double bitwise NOT has no effect."
179	                }
180	            },
181	        };
182	
183	        Some(
184	            RuleDiagnostic::new(
185	                rule_category!(),
186	                state.range,
187	                markup! {{message}},
188	            )
189	            .note(markup! {
190	                "This expression already evaluates to "{article}"."
191	            })
192	            .note(markup! {{note}})
193	            .note(markup! {
194	                "Redundant conversions make it harder to see that the value already has the expected "{name}" type."
195	            }),
196	        )
197	    }
198	}
