14	use biome_rule_options::no_equals_to_null::NoEqualsToNullOptions;
15	
16	declare_lint_rule! {
17	    /// Require the use of `===` or `!==` for comparison with `null`.
18	    ///
19	    /// Comparing to `null` with `==` or `!=` may have unintended results as the
20	    /// expression evaluates to `true` when comparing `null` to `undefined`.
21	    ///
22	    /// ## Examples
23	    ///
24	    /// ### Invalid
25	    ///
26	    /// ```js,expect_diagnostic
27	    /// foo == null;
28	    /// ```
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// foo != null;
32	    /// ```
33	    ///
34	    /// ### Valid
35	    ///
36	    /// ```js
37	    /// foo === null;
38	    /// ```
39	    ///
40	    /// ```js
41	    /// foo !== null;
42	    /// ```
43	    pub NoEqualsToNull {
44	        version: "2.3.8",
45	        name: "noEqualsToNull",
46	        language: "js",
47	        sources: &[RuleSource::Eslint("no-eq-null").same()],
48	        recommended: false,
49	        severity: Severity::Error,
50	        fix_kind: FixKind::Unsafe,
51	    }
52	}
53	
54	impl Rule for NoEqualsToNull {
55	    type Query = Ast<JsBinaryExpression>;
56	    type State = JsSyntaxToken;
57	    type Signals = Option<Self::State>;
58	    type Options = NoEqualsToNullOptions;
59	
60	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
61	        let node = ctx.query();
62	        let op = node.operator_token().ok()?;
63	
64	        if matches!(op.kind(), EQ2 | NEQ)
65	            && (is_null_literal(&node.left()) || is_null_literal(&node.right()))
66	        {
67	            return Some(op);
68	        }
69	
70	        None
71	    }
72	
73	    fn diagnostic(_ctx: &RuleContext<Self>, op: &Self::State) -> Option<RuleDiagnostic> {
74	        let text_trimmed = op.text_trimmed();
75	        Some(RuleDiagnostic::new(
76	            rule_category!(),
77	            op.text_trimmed_range(),
78	            markup! {
79	                ""<Emphasis>"null"</Emphasis>" comparison with "<Emphasis>{text_trimmed}</Emphasis>" is disallowed."
80	            },
81	        ))
82	    }
83	
84	    fn action(ctx: &RuleContext<Self>, op: &Self::State) -> Option<JsRuleAction> {
85	        let mut mutation = ctx.root().begin();
86	
87	        let suggestion = if op.kind() == EQ2 { T![===] } else { T![!==] };
88	        mutation.replace_token(op.clone(), make::token(suggestion));
89	
90	        Some(JsRuleAction::new(
91	            ctx.metadata().action_category(ctx.category(), ctx.group()),
92	            ctx.metadata().applicability(),
93	            markup! { "Use "<Emphasis>{suggestion.to_string()?}</Emphasis>" instead." }.to_owned(),
94	            mutation,
95	        ))
96	    }
97	}
98	
99	fn is_null_literal(res: &SyntaxResult<AnyJsExpression>) -> bool {
100	    matches!(
101	        res,
102	        Ok(AnyJsExpression::AnyJsLiteralExpression(
103	            AnyJsLiteralExpression::JsNullLiteralExpression(_)
104	        ))
105	    )
106	}
