use biome_rowan::{AstNode, AstNodeExt, AstSeparatedList, BatchMutationExt, TextRange};
use biome_rule_options::use_reduce_type_parameter::UseReduceTypeParameterOptions;

declare_lint_rule! {
    /// Prefer using a type parameter over a type assertion on the initial value of `Array#reduce`.
    ///
    /// When the initial value of an `Array#reduce` (or `Array#reduceRight`) call uses a type
    /// assertion, TypeScript can no longer check that the reducer callback actually returns a
    /// compatible value. Passing the type as a type parameter on the call instead keeps the type
    /// safety, because TypeScript will verify that the accumulator and the callback return type
    /// match the annotated type.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduce((acc, value) => [...acc, value], [] as number[]);
    /// ```
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduce((acc, value) => [...acc, value], <number[]>[]);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```ts
    /// [1, 2, 3].reduce<number[]>((acc, value) => [...acc, value], []);
    /// ```
    ///
    /// ```ts
    /// [1, 2, 3].reduce((acc, value) => acc + value, 0);
    /// ```
    pub UseReduceTypeParameter {
        version: "next",
        name: "useReduceTypeParameter",
        language: "ts",
        recommended: false,
        severity: Severity::Information,
        fix_kind: FixKind::Unsafe,
    }
}

#[derive(Clone, Copy)]
enum ReduceMethod {
    Reduce,
    ReduceRight,
}

impl ReduceMethod {
    fn as_str(self) -> &'static str {
        match self {
            Self::Reduce => "reduce",
            Self::ReduceRight => "reduceRight",
        }
    }
}

pub struct RuleState {
    method: ReduceMethod,
    /// The initial value argument as it is written, including any parentheses.
    initial_value: AnyJsExpression,
    /// The expression the assertion is applied to, with the assertion removed.
    inner: AnyJsExpression,
    /// The type that is being asserted.
    asserted_type: AnyTsType,
    /// Whether the call already has a type parameter.
    has_type_parameter: bool,
    /// The range of the type assertion, used to point the diagnostic.
    range: TextRange,
}

impl Rule for UseReduceTypeParameter {
    type Query = Ast<JsCallExpression>;
    type State = RuleState;
    type Signals = Option<Self::State>;
    type Options = UseReduceTypeParameterOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();

        let callee = call.callee().ok()?.omit_parentheses();
        let member_expression = callee.as_js_static_member_expression()?;
        let member = member_expression.member().ok()?;
        let method = match member.value_token().ok()?.text_trimmed() {
            "reduce" => ReduceMethod::Reduce,
            "reduceRight" => ReduceMethod::ReduceRight,
            _ => return None,
        };

        // `reduce`/`reduceRight` must be called with a callback and an initial value.
        let args = call.arguments().ok()?.args();
        if args.len() != 2 {
            return None;
        }
        let initial_value = args.into_iter().nth(1)?.ok()?;
        let initial_value = initial_value.as_any_js_expression()?.clone();

        // Unwrap parentheses to reach the assertion, e.g. `([] as number[])`.
        let (inner, asserted_type, range) = match initial_value.clone().omit_parentheses() {
            AnyJsExpression::TsAsExpression(assertion) => (
                assertion.expression().ok()?,
                assertion.ty().ok()?,
                assertion.range(),
            ),
            AnyJsExpression::TsTypeAssertionExpression(assertion) => (
                assertion.expression().ok()?,
                assertion.ty().ok()?,
                assertion.range(),
            ),
            // `satisfies` and non-asserted values are allowed.
            _ => return None,
        };

        Some(RuleState {
            method,
            initial_value,
            inner,
            asserted_type,
            has_type_parameter: call.type_arguments().is_some(),
            range,
        })
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let message = match state.method {
            ReduceMethod::Reduce => "The initial value of Array#reduce uses a type assertion.",
            ReduceMethod::ReduceRight => {
                "The initial value of Array#reduceRight uses a type assertion."
            }
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, markup! { {message} }).note(markup! {
                "Type assertions can hide type mismatches in the reducer callback. Use a type parameter on the call instead, so TypeScript checks the return type."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<JsRuleAction> {
        let mut mutation = ctx.root().begin();

        let message = if state.has_type_parameter {
            // The call already has a type parameter, so only drop the assertion.
            mutation.replace_node(state.initial_value.clone(), state.inner.clone());
            markup! { "Remove the type assertion from the initial value." }.to_owned()
        } else {
            // Move the asserted type to a type parameter and drop the assertion.
            let call = ctx.query();
            let new_arguments = call
                .arguments()
                .ok()?
                .replace_node(state.initial_value.clone(), state.inner.clone())?;

            let type_arguments = make::ts_type_arguments(
                make::token(T![<]),
                make::ts_type_argument_list(Some(state.asserted_type.clone().trim_trivia()?), None),
                make::token(T![>]),
            );

            let mut builder = make::js_call_expression(call.callee().ok()?, new_arguments);
            if let Some(optional_chain_token) = call.optional_chain_token() {
                builder = builder.with_optional_chain_token(optional_chain_token);
            }
            let new_call = builder.with_type_arguments(type_arguments).build();

            mutation.replace_node(call.clone(), new_call);
            markup! { "Use a type parameter instead of type assertion." }.to_owned()
        };

        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            message,
            mutation,
        ))
    }
}
