            ReduceMethod::Reduce => "The initial value of Array#reduce uses a type assertion.",
            ReduceMethod::ReduceRight => {
                "The initial value of Array#reduceRight uses a type assertion."
            }
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, markup! { {message} }).note(markup! {
                "Type assertions can hide type mismatches in the reducer callback. Use a type parameter on the call instead, so TypeScript checks the return type."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<JsRuleAction> {
        let mut mutation = ctx.root().begin();

        let message = if state.has_type_parameter {
            // The call already has a type parameter, so only drop the assertion.
            mutation.replace_node(state.initial_value.clone(), state.inner.clone());
            markup! { "Remove the type assertion from the initial value." }.to_owned()
        } else {
            // Move the asserted type to a type parameter and drop the assertion.
            let call = ctx.query();
            let new_arguments = call
                .arguments()
                .ok()?
                .replace_node(state.initial_value.clone(), state.inner.clone())?;

            let type_arguments = make::ts_type_arguments(
                make::token(T![<]),
                make::ts_type_argument_list(Some(state.asserted_type.clone().trim_trivia()?), None),
                make::token(T![>]),
            );

            let mut builder = make::js_call_expression(call.callee().ok()?, new_arguments);
            if let Some(optional_chain_token) = call.optional_chain_token() {
                builder = builder.with_optional_chain_token(optional_chain_token);
            }
            let new_call = builder.with_type_arguments(type_arguments).build();

            mutation.replace_node(call.clone(), new_call);
            markup! { "Use a type parameter instead of type assertion." }.to_owned()
        };

        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            message,
            mutation,
        ))
    }
